package io.meridian.cardvault.infrastructure;

import io.meridian.cardvault.application.KeyManagement;
import io.meridian.common.tenancy.TenantContext;
import io.meridian.common.time.Clocks;
import java.security.Provider;
import java.time.Duration;
import java.time.OffsetDateTime;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;

/**
 * Envelope encryption (GAP-01): each vault key is a data key generated by the {@link KeyManagement} master key (AWS
 * KMS in production), stored only wrapped ({@code card_vault_key.wrapped_key}, with the master key reference), and
 * unwrapped on first use. The encryption context of every wrap is {@code tenant} + {@code purpose} (key type) +
 * {@code key} (label and version), so a wrapped key moved to another tenant's row or another purpose fails to unwrap.
 *
 * <p>Unwrapped data keys are cached in memory per tenant and key for {@code ttl} (and at most {@code maxEntries}),
 * which bounds KMS calls to one Decrypt per key per TTL per pod. Rotating the master key re-wraps the data keys
 * ({@link #rewrap}: KMS ReEncrypt, server side); records encrypted under a data key are untouched.
 *
 * <p>Keys created before envelope encryption have no stored envelope; they are derived from the legacy software
 * master key ({@link SoftwareHsm#deriveKey}) when one is configured, and {@link #rewrap} adopts them (wraps the
 * derived material under the master key) so the legacy key can be retired.
 */
public class EnvelopeHsm extends JcaHsm {
    private record Cached(SecretKeySpec key, OffsetDateTime expires) {}

    private final KeyManagement kms;
    private final byte[] legacyMaster;
    private final Duration ttl;
    private final int maxEntries;
    private final Map<String, Cached> cache = new ConcurrentHashMap<>();

    /**
     * @param legacyMaster software master key of keys created before envelope encryption (null: none may exist)
     */
    public EnvelopeHsm(KeyManagement kms, byte[] legacyMaster, Duration ttl, int maxEntries) {
        super("GenericSecret");
        this.kms = kms;
        this.legacyMaster = legacyMaster == null ? null : legacyMaster.clone();
        this.ttl = ttl;
        this.maxEntries = maxEntries;
    }

    /** The encryption context of a key: tenant + purpose + label/version. */
    static Map<String, String> context(KeyRef ref) {
        Map<String, String> ctx = new LinkedHashMap<>();
        ctx.put("tenant", TenantContext.require().toString());
        ctx.put("purpose", ref.type() == null ? "UNSPECIFIED" : ref.type());
        ctx.put("key", ref.name());
        return ctx;
    }

    private String cacheKey(KeyRef ref) {
        // the full encryption context plus the master key: a cache hit never bypasses a context KMS would refuse
        return TenantContext.require() + "|" + ref.type() + "|" + ref.name() + "|" + ref.masterRef();
    }

    @Override
    protected SecretKey key(KeyRef ref) {
        if (ref.wrapped() == null) {
            return legacy(ref);
        }
        String ck = cacheKey(ref);
        OffsetDateTime now = Clocks.now();
        Cached c = cache.get(ck);
        if (c != null && c.expires().isAfter(now)) {
            return c.key();
        }
        byte[] plain = kms.decrypt(new KeyManagement.WrappedKey(ref.masterRef(), ref.wrapped()), context(ref));
        try {
            return remember(ck, plain);
        } finally {
            Arrays.fill(plain, (byte) 0);
        }
    }

    private SecretKeySpec legacy(KeyRef ref) {
        if (legacyMaster == null) {
            throw new IllegalStateException("key " + ref.name() + " has no wrapped data key and no legacy master key is "
                    + "configured (meridian.cards.vault.master-key); restore it and run the master key re-wrap");
        }
        byte[] plain = SoftwareHsm.deriveKey(legacyMaster, ref.label(), ref.version());
        try {
            return new SecretKeySpec(plain, "AES");
        } finally {
            Arrays.fill(plain, (byte) 0);
        }
    }

    private SecretKeySpec remember(String ck, byte[] plain) {
        if (cache.size() >= maxEntries) {
            OffsetDateTime now = Clocks.now();
            cache.values().removeIf(x -> !x.expires().isAfter(now));
            if (cache.size() >= maxEntries) {
                cache.clear();
            }
        }
        SecretKeySpec k = new SecretKeySpec(plain, "AES");
        cache.put(ck, new Cached(k, Clocks.now().plus(ttl)));
        return k;
    }

    @Override
    protected Provider provider() {
        return null;
    }

    @Override
    public KeyMaterial createKey(KeyRef key) {
        KeyManagement.DataKey dk = kms.generateDataKey(context(key));
        try {
            SecretKeySpec k = remember(cacheKey(new KeyRef(key.type(), key.label(), key.version(), dk.wrapped().ciphertext(),
                    dk.wrapped().masterRef())), dk.plaintext());
            return new KeyMaterial(dk.wrapped().ciphertext(), dk.wrapped().masterRef(), kcv(k));
        } finally {
            Arrays.fill(dk.plaintext(), (byte) 0);
        }
    }

    @Override
    public KeyMaterial rewrap(KeyRef key) {
        Map<String, String> ctx = context(key);
        if (key.wrapped() == null) {
            SecretKeySpec legacy = legacy(key);
            byte[] plain = legacy.getEncoded();
            try {
                KeyManagement.WrappedKey w = kms.wrap(plain, ctx);
                return new KeyMaterial(w.ciphertext(), w.masterRef(), kcv(legacy));
            } finally {
                Arrays.fill(plain, (byte) 0);
            }
        }
        KeyManagement.WrappedKey w = kms.reWrap(new KeyManagement.WrappedKey(key.masterRef(), key.wrapped()), ctx);
        return new KeyMaterial(w.ciphertext(), w.masterRef(),
                kcv(new KeyRef(key.type(), key.label(), key.version(), w.ciphertext(), w.masterRef())));
    }

    @Override
    public String currentMasterRef() {
        return kms.currentMasterRef();
    }

    @Override
    public boolean pinInsideHsm() {
        return false;
    }

    @Override
    public String describe() {
        return "envelope encryption, " + kms.describe() + ", data key cache " + ttl
                + (legacyMaster != null ? ", legacy derived keys readable" : "");
    }

    /** Drops every cached data key (tests, operator flush after a master key incident). */
    public void flush() {
        cache.clear();
    }
}
